import Complex64Array = require( '@stdlib/array/complex64' );
import Complex64 = require( '@stdlib/complex/float32/ctor' );
import cfillNaN = require( './index' );


// TESTS //

// The function returns a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN( x.length, alpha, x, 1 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN( '10', alpha, x, 1 ); // $ExpectError
	cfillNaN( true, alpha, x, 1 ); // $ExpectError
	cfillNaN( false, alpha, x, 1 ); // $ExpectError
	cfillNaN( null, alpha, x, 1 ); // $ExpectError
	cfillNaN( undefined, alpha, x, 1 ); // $ExpectError
	cfillNaN( [], alpha, x, 1 ); // $ExpectError
	cfillNaN( {}, alpha, x, 1 ); // $ExpectError
	cfillNaN( ( x: number ): number => x, alpha, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not complex-like...
{
	const x = new Complex64Array( 10 );

	cfillNaN( x.length, 10, x, 1 ); // $ExpectError
	cfillNaN( x.length, '10', x, 1 ); // $ExpectError
	cfillNaN( x.length, true, x, 1 ); // $ExpectError
	cfillNaN( x.length, false, x, 1 ); // $ExpectError
	cfillNaN( x.length, null, x, 1 ); // $ExpectError
	cfillNaN( x.length, undefined, x, 1 ); // $ExpectError
	cfillNaN( x.length, [ '1' ], x, 1 ); // $ExpectError
	cfillNaN( x.length, {}, x, 1 ); // $ExpectError
	cfillNaN( x.length, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN( x.length, alpha, 10, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, '10', 1 ); // $ExpectError
	cfillNaN( x.length, alpha, true, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, false, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, null, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, undefined, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, [ '1' ], 1 ); // $ExpectError
	cfillNaN( x.length, alpha, {}, 1 ); // $ExpectError
	cfillNaN( x.length, alpha, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN( x.length, alpha, x, '10' ); // $ExpectError
	cfillNaN( x.length, alpha, x, true ); // $ExpectError
	cfillNaN( x.length, alpha, x, false ); // $ExpectError
	cfillNaN( x.length, alpha, x, null ); // $ExpectError
	cfillNaN( x.length, alpha, x, undefined ); // $ExpectError
	cfillNaN( x.length, alpha, x, [] ); // $ExpectError
	cfillNaN( x.length, alpha, x, {} ); // $ExpectError
	cfillNaN( x.length, alpha, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN(); // $ExpectError
	cfillNaN( x.length ); // $ExpectError
	cfillNaN( x.length, alpha ); // $ExpectError
	cfillNaN( x.length, alpha, x ); // $ExpectError
	cfillNaN( x.length, alpha, x, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray( x.length, alpha, x, 1, 0 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray( '10', alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( true, alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( false, alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( null, alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( undefined, alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( [], alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( {}, alpha, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( ( x: number ): number => x, alpha, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not complex-like...
{
	const x = new Complex64Array( 10 );

	cfillNaN.ndarray( x.length, 10, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, '10', x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, true, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, false, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, null, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, undefined, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, [ '1' ], x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, {}, x, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray( x.length, alpha, 10, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, '10', 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, true, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, false, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, null, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, undefined, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, [ '1' ], 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, {}, 1, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray( x.length, alpha, x, '10', 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, true, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, false, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, null, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, undefined, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, [], 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, {}, 0 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray( x.length, alpha, x, 1, '10' ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, true ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, false ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, null ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, undefined ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, [] ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, {} ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );
	const alpha = new Complex64( 2.0, 2.0 );

	cfillNaN.ndarray(); // $ExpectError
	cfillNaN.ndarray( x.length ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1 ); // $ExpectError
	cfillNaN.ndarray( x.length, alpha, x, 1, 0, 10 ); // $ExpectError
}
